INSERT INTO `announcements` (`id`, `title`, `audience`, `content`, `attachment`, `sender`, `created_at`, `updated_at`) VALUES
(1, 'REGISTRATION (KWIYANDIKISHA)', 'public', 'We have already started the registration for this coming academic year of 2025-2026. \r\nRegister now for securing your place! \r\n\r\nwelcome in ESA!', 'announcements/yK4Bchy8m98FmGrXAJAdDY6aQf21Fh2dPBQnXq1e.html', 'EXCELLENT SERVANT ACADEMY', '2025-07-19 17:00:48', '2026-01-06 20:05:39'),
(2, 'NEW ACADEMIC YEAR (2025/2026) OPENING', 'public', 'Hey, Did you know that we will start the new academic year 2025/2026 on 04.Aug.2025? the following are the reasons:\r\n1. We teach program of 3 years in only one year or less \r\n2. The curriculum has changed (new combinations, new modules, new grading system) \r\n3. we train students who are weak in English', NULL, 'EXCELLENT SERVANT ACADEMY', '2025-07-19 17:08:01', '2025-07-19 17:08:01'),
(3, 'MUSANZE DAY-TRIP (28/11/2025)', 'students', 'Dear Students we would like to inform you that we have a trip on friday 28th.11.2025! \r\nthis trip is compulsary for all tourism students and they should join it after completing all requirements (full payments of the school fees and Trip fee)! \r\nfor the further information you can ask the office staff. \r\n\r\nHave wonderful preparation!\r\nDone by Headmaste Theophile!', NULL, 'EXCELLENT SERVANT ACADEMY', '2025-10-12 19:49:38', '2025-10-12 20:23:35');
