INSERT INTO `questions` (`id`, `exam_id`, `question_type`, `text`, `option_a`, `option_b`, `option_c`, `option_d`, `correct_answer`, `correct_answers`, `explanation`, `keywords`, `marks`, `weight`, `difficulty_level`, `created_at`, `updated_at`, `question_bank_id`, `subject_area`, `biology_topic`, `diagram_labels`, `question_image`) VALUES
(2, NULL, '$x = -2$', '$x = -3$', '$x = 2$', '$x = 3$', 'option_1', '2', 'Factor the quadratic: $(x+2)(x+3) = 0$, so x = -2 or x = -3. Since this is multiple choice, we select one correct answer.', NULL, 'mathematics', 'roots', 2, 1.00, 1, '2026-03-18 12:45:15', '2026-03-18 12:45:15', 1, '', 'quadratic equation', 'factoring', NULL),
(3, NULL, '$f\'(x) = 3x^2 + 4x - 5$', '$f\'(x) = 3x^2 + 4x + 5$', '$f\'(x) = x^2 + 4x - 5$', '$f\'(x) = 3x^2 - 5$', 'option_1', '3', 'Apply the power rule: $\\frac{d}{dx}[x^n] = nx^{n-1}$. So $\\frac{d}{dx}[x^3] = 3x^2$, $\\frac{d}{dx}[2x^2] = 4x$, and $\\frac{d}{dx}[-5x] = -5$.', NULL, 'mathematics', 'power rule', 3, 1.20, 1, '2026-03-18 12:45:15', '2026-03-18 12:45:15', 1, '', 'derivative', 'calculus', NULL),
(4, NULL, '$\\frac{1}{3}$', '$\\frac{1}{2}$', '$1$', '$\\frac{3}{2}$', 'option_1', '2', '$\\int x^2 dx = \\frac{x^3}{3} + C$. Evaluating from 0 to 1: $\\frac{1^3}{3} - \\frac{0^3}{3} = \\frac{1}{3}$.', NULL, 'mathematics', 'definite integral', 2, 1.00, 1, '2026-03-18 12:45:15', '2026-03-18 12:45:15', 1, '', 'integral', 'calculus', NULL),
(5, NULL, '$\\frac{1}{2}$', '$\\frac{\\sqrt{3}}{2}$', '$\\frac{\\sqrt{2}}{2}$', '$1$', 'option_1', '1', '$\\sin(\\frac{\\pi}{6}) = \\sin(30°) = \\frac{1}{2}$', NULL, 'mathematics', 'unit circle', 1, 0.80, 1, '2026-03-18 12:45:15', '2026-03-18 12:45:15', 1, '', 'trigonometry', 'sine', NULL),
(6, NULL, '$x - 3$', '$x + 3$', '$x^2 - 6$', '$\\frac{x^2 - 9}{x + 3}$', 'option_1', '1', 'Factor numerator: $x^2 - 9 = (x - 3)(x + 3)$. Cancel $(x + 3)$ terms: $\\frac{(x - 3)(x + 3)}{x + 3} = x - 3$', NULL, 'mathematics', 'factoring', 1, 0.90, 1, '2026-03-18 12:45:15', '2026-03-18 12:45:15', 1, '', 'algebra', 'simplification', NULL),
(7, NULL, 'multiple_choice', 'Evaluate the limit: $\\lim_{x \\to 1} (x + 1)$', '$1$', '$2$', '$1$', '$3$', 'B', NULL, 'Substitute x=1: 1+1=2.', 'limit,calculus', 1, 1.00, 1, '2026-03-18 12:45:15', '2026-03-18 12:45:15', 1, 'Calculus', '', '', NULL),
